{"command": "create", "path": "/app/workspace/extract.py", "file_text": """"Extract date and total_amount from receipt images into an Excel file."""
import os
import re
from pathlib import Path

import pytesseract
from PIL import Image, ImageOps, ImageFilter
from openpyxl import Workbook

IMG_DIR = Path("/app/workspace/dataset/img")
OUT_FILE = Path("/app/workspace/stat_ocr.xlsx")

# -------------------- OCR --------------------
def ocr_variants(path: Path):
    """Return a list of OCR text variants from an image."""
    img = Image.open(path)
    variants = [img]

    # Grayscale + autocontrast
    g = ImageOps.grayscale(img)
    variants.append(ImageOps.autocontrast(g, cutoff=2))

    # Upscaled
    w, h = img.size
    if max(w, h) < 2000:
        up = g.resize((w * 2, h * 2), Image.LANCZOS)
        variants.append(ImageOps.autocontrast(up, cutoff=2))

    texts = []
    configs = ["--psm 6", "--psm 4", "--psm 11"]
    for v in variants:
        for cfg in configs:
            try:
                t = pytesseract.image_to_string(v, config=cfg)
                texts.append(t)
            except Exception:
                pass
    return texts


# -------------------- Date extraction --------------------
MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}


def normalise_year(y: int) -> int:
    if y < 100:
        return 2000 + y if y < 70 else 1900 + y
    return y


def validate_date(d: int, m: int, y: int):
    if not (1 <= m <= 12):
        return None
    if not (1 <= d <= 31):
        return None
    if not (2000 <= y <= 2099):
        return None
    return f"{y:04d}-{m:02d}-{d:02d}"


def extract_date(text: str):
    """Extract date in YYYY-MM-DD from OCR text. Returns None if not found."""
    candidates = []

    # DD/MM/YYYY or DD-MM-YYYY or DD.MM.YYYY
    for m in re.finditer(r"(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{2,4})", text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        y = normalise_year(y)
        ds = validate_date(d, mo, y)
        if ds:
            candidates.append((m.start(), ds))

    # YYYY-MM-DD or YYYY/MM/DD
    for m in re.finditer(r"(\d{4})[\/\-\.](\d{1,2})[\/\-\.](\d{1,2})", text):
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        ds = validate_date(d, mo, y)
        if ds:
            candidates.append((m.start(), ds))

    # DD Mon YYYY
    for m in re.finditer(
        r"(\d{1,2})\s+([A-Za-z]{3,9})\.?\s+(\d{2,4})", text
    ):
        d = int(m.group(1))
        mo_name = m.group(2).lower().rstrip(".")
        if mo_name not in MONTHS:
            continue
        mo = MONTHS[mo_name]
        y = normalise_year(int(m.group(3)))
        ds = validate_date(d, mo, y)
        if ds:
            candidates.append((m.start(), ds))

    if not candidates:
        return None

    # Prefer a date appearing near a "date"-like keyword.
    lowered = text.lower()
    best = None
    best_score = -1
    for pos, ds in candidates:
        # Score: proximity to "date" keyword
        score = 0
        # Search backwards 60 chars for "date" keyword
        window = lowered[max(0, pos - 60):pos]
        if "date" in window or "bizdate" in window:
            score += 10
        if score > best_score:
            best = ds
            best_score = score
    if best_score < 0:
        return candidates[0][1]
    return best


# -------------------- Amount extraction --------------------
AMOUNT_RE = re.compile(r"\d{1,3}(?:,\d{3})*\.\d{2}|\d+\.\d{2}")


def normalise_amount(s: str) -> str:
    return s.replace(",", "")


def extract_amounts(line: str):
    """Return list of (match_start, amount_string) in reading order."""
    return [(m.start(), normalise_amount(m.group(0))) for m in AMOUNT_RE.finditer(line)]


PRIORITY_KEYWORDS = [
    # Tier 0: GRAND TOTAL
    ["GRAND TOTAL"],
    # Tier 1: TOTAL RM, TOTAL: RM
    ["TOTAL RM", "TOTAL: RM", "TOTAL:RM", "TOTAL (RM)"],
    # Tier 2: TOTAL AMOUNT
    ["TOTAL AMOUNT"],
    # Tier 3: TOTAL/AMOUNT/etc.
    [
        "NET TOTAL", "NETT TOTAL",
        "TOTAL DUE", "AMOUNT DUE", "BALANCE DUE",
        "TOTAL", "AMOUNT",
    ],
]

EXCLUSION_HARD = ["SUBTOTAL", "SUB TOTAL", "SUB-TOTAL",
                  "DISCOUNT", "CHANGE", "CASH TENDERED",
                  "SAVING", "QTY", "QUANTITY", "ITEM COUNT",
                  "COUNT", "TENDER"]

TAX_WORDS = ["TAX", "GST", "SST", "VAT"]


def is_excluded(line_upper: str) -> bool:
    for ex in EXCLUSION_HARD:
        if ex in line_upper:
            return True
    # Tax words: exclude unless "INCL" or "AFTER" appears (meaning inclusive/post-tax)
    for ex in TAX_WORDS:
        if ex in line_upper:
            if "INCL" not in line_upper and "AFTER" not in line_upper:
                return True
    return False


def matches_tier(line_upper: str, tier_keywords):
    for kw in tier_keywords:
        if kw in line_upper:
            return True
    return False


def extract_total(text: str):
    """Extract total amount string (e.g. '47.70') from OCR text."""
    lines = [ln for ln in text.splitlines()]

    # Find end-of-main region: before "GST SUMMARY", "TAX SUMMARY", "GST CODE",
    # "TAX CODE" or "SUMMARY" alone.
    end_idx = len(lines)
    summary_markers = ["GST SUMMARY", "TAX SUMMARY", "GST CODE", "TAX CODE"]
    for i, ln in enumerate(lines):
        u = ln.upper()
        if any(mk in u for mk in summary_markers):
            end_idx = i
            break

    main_lines = lines[:end_idx]

    for tier_kws in PRIORITY_KEYWORDS:
        candidates = []
        for i, ln in enumerate(main_lines):
            u = ln.upper()
            if not matches_tier(u, tier_kws):
                continue
            if is_excluded(u):
                continue
            amounts = extract_amounts(ln)
            if amounts:
                # Pick last numeric on same line (rightmost)
                _, amt = amounts[-1]
                candidates.append((i, amt))
            else:
                # Fallback: last number on next line
                if i + 1 < len(main_lines):
                    nxt_amts = extract_amounts(main_lines[i + 1])
                    if nxt_amts:
                        _, amt = nxt_amts[-1]
                        candidates.append((i, amt))
        if candidates:
            # Pick last (most bottom) candidate
            return candidates[-1][1]

    return None


def format_amount(a):
    if a is None:
        return None
    try:
        val = float(a)
    except ValueError:
        return None
    return f"{val:.2f}"


# -------------------- Main pipeline --------------------
def process_image(path: Path):
    best_date = None
    best_total = None
    for text in ocr_variants(path):
        if best_date is None:
            best_date = extract_date(text)
        if best_total is None:
            best_total = extract_total(text)
        if best_date and best_total:
            break
    return best_date, format_amount(best_total)


def main():
    files = sorted(IMG_DIR.glob("*.png")) + sorted(IMG_DIR.glob("*.jpg")) + sorted(IMG_DIR.glob("*.jpeg"))
    files = sorted(set(files), key=lambda p: p.name)

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])

    for p in files:
        date_s, total_s = process_image(p)
        print(f"{p.name}: date={date_s}, total={total_s}")
        ws.append([p.name, date_s, total_s])

    wb.save(OUT_FILE)
    print(f"\nSaved to {OUT_FILE}")


if __name__ == "__main__":
    main()
