    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}


def normalise_year(y: int) -> int:
    if y < 100:
        return 2000 + y if y < 70 else 1900 + y
    return y


def validate_date(d: int, m: int, y: int):
    if not (1 <= m <= 12):
        return None
    if not (1 <= d <= 31):
        return None
    if not (2000 <= y <= 2099):
        return None
    return f"{y:04d}-{m:02d}-{d:02d}"


